// Accepts a LinkedIn post URL or URN plus the comment text, and normalises
// them into what the LinkedIn Comments API expects.
const MAX_COMMENT_LENGTH = 1250;

return $input.all().map((item) => {
  const body = item.json.body || {};
  const rawPost = String(body.post ?? body.postUrl ?? body.postUrn ?? '').trim();
  const text = String(body.text ?? body.comment ?? '').trim();
  const actorUrn = String(item.json.actorUrn || '').trim();
  const errors = [];

  let decoded = rawPost;
  try {
    decoded = decodeURIComponent(rawPost);
  } catch (e) {}

  // Handles urn:li:activity:123, .../feed/update/urn:li:share:123/,
  // and .../posts/some-slug-activity-123-AbCd or ...-ugcPost-123-AbCd
  const match = decoded.match(/(activity|share|ugcPost)[:-](\d{10,25})/);
  const postUrn = match ? `urn:li:${match[1]}:${match[2]}` : null;

  if (!rawPost) errors.push('Missing "post" (LinkedIn post URL or URN).');
  else if (!postUrn) errors.push(`Could not find a post ID in "${rawPost}".`);
  if (!text) errors.push('Missing "text" (the comment to post).');
  else if (text.length > MAX_COMMENT_LENGTH) {
    errors.push(`"text" is ${text.length} characters; LinkedIn allows ${MAX_COMMENT_LENGTH}.`);
  }
  if (!/^urn:li:(person|organization):[\w-]+$/.test(actorUrn) || actorUrn.endsWith('REPLACE_ME')) {
    errors.push('Config node: set actorUrn to your urn:li:person:... or urn:li:organization:... value.');
  }

  return {
    json: {
      valid: errors.length === 0,
      errors,
      postUrn,
      text,
      actorUrn,
      linkedinVersion: item.json.linkedinVersion,
    },
  };
});
